mapper.select:
SELECT id, name, source_type, location, location_hash, username, password_encrypted, parser_profile_id, created_at, updated_at, scan_enabled, scan_cron, next_scan_at, last_scan_at, last_scan_status, last_scan_error
FROM media_source
ORDER BY created_at DESC, id ASC
LIMIT #{limit}
OFFSET #{offset}

SELECT id, name, source_type, location, location_hash, username, password_encrypted, parser_profile_id, created_at, updated_at, scan_enabled, scan_cron, next_scan_at, last_scan_at, last_scan_status, last_scan_error
FROM media_source
